/** Public learning material. Rewarded quiz keys belong exclusively in school-answers. */
export const KQ_SCHOOL_CONTENT_VERSION = "2026-11-11.1";
export const KQ_SCHOOL_VERIFIED_AT = "2026-11-11";

export type KqSchoolSource = Readonly<{ id: string; title: string; organization: string; url: string; verifiedAt: string; note?: string }>;
export type KqSchoolQuestion = Readonly<{
  id: string; prompt: string; options: readonly Readonly<{ id: string; text: string }>[];
  difficulty: "easy" | "medium"; lessonId: string; sectionId: string;
  sources: readonly KqSchoolSource[]; buddyCodes?: readonly string[];
}>;
export type KqSchoolModule = Readonly<{ id: string; title: string; version: string; questions: readonly KqSchoolQuestion[] }>;
export type KqSchoolCourse = Readonly<{
  id: string; quizId: string; title: string; objective: string; readingMinutes: number;
  sections: readonly Readonly<{ id: string; title: string; paragraphs: readonly string[] }>[];
  observation: string; example: string; exercise: string;
  buddyCodes: readonly string[]; workshopIds: readonly string[]; sources: readonly KqSchoolSource[];
}>;

function source(id: string, title: string, organization: string, url: string, note?: string): KqSchoolSource {
  return { id, title, organization, url, verifiedAt: KQ_SCHOOL_VERIFIED_AT, ...(note ? { note } : {}) };
}
