export function getKqSchoolSource(id: string): KqSchoolSource | undefined { return KQ_SCHOOL_SOURCES.find(item => item.id === id); }
function sources(...ids: string[]): KqSchoolSource[] {
  return ids.map(id => { const found = getKqSchoolSource(id); if (!found) throw new Error(`Unknown school source: ${id}`); return found; });
}
function course(id: string, title: string, objective: string, sections: readonly (readonly [string, string, string])[], observation: string, exercise: string, sourceIds: string[], buddyCodes: string[], workshopIds: string[]): KqSchoolCourse {
  return { id, quizId: id, title, objective, readingMinutes: 4, sections: sections.map(([title, first, second], index) => ({ id: `${id}-${index + 1}`, title, paragraphs: [first, second] })), observation, example: observation, exercise, sources: sources(...sourceIds), buddyCodes, workshopIds };
}
export const KQ_SCHOOL_COURSES: readonly KqSchoolCourse[] = [
  course("plant", "Découvrir la plante", "Reconnaître les organes et expliquer le rôle du pollen.", [
    ["Une identité botanique", "Bienvenue au tableau des botanistes. Cannabis sativa L. est le nom scientifique accepté par Kew ; la plante appartient aux Cannabacées, comme le houblon. Un nom scientifique sert à partager une référence. Les mots chanvre et cannabis changent de sens selon que l’on parle de botanique, de filière ou de droit : on précisera toujours le contexte.", "Une feuille dessinée sur une enseigne ne raconte donc pas toute la plante. Elle ne révèle ni une concentration mesurée, ni un usage autorisé. Les personnages du Quartier aident à mémoriser, mais ne sont pas des spécimens d’herbier : L’Arbre Mère est présenté dans sa fiche comme une création du jeu, pas comme un ancêtre réel."],
    ["Les organes travaillent ensemble", "Les feuilles sont un lieu majeur de photosynthèse : avec la lumière, la plante transforme de l’eau et du dioxyde de carbone en matière organique. Une feuille composée possède plusieurs folioles ; ce ne sont pas autant de feuilles indépendantes. L’aspect palmé rappelle une main, avec des parties qui rayonnent depuis un point commun.", "Les racines assurent l’ancrage et participent à l’absorption de l’eau et des éléments minéraux. La tige porte les organes et contient des tissus de transport. Les fleurs concernent la reproduction. Retenir ces fonctions évite de confondre une fleur, une feuille, une graine et un fragment de tige lorsqu’on lit une description de matière première."],
    ["Le trajet du pollen", "Le pollen provient des organes mâles. Chez le chanvre, son transport se fait principalement par le vent : on dit que la pollinisation est anémophile. La pollinisation désigne l’arrivée du pollen sur une partie réceptrice de la fleur ; la fécondation qui peut suivre est une étape distincte. Transport et rencontre des cellules ne sont pas synonymes.", "Une plante dioïque porte les fleurs mâles et femelles sur des individus différents ; une plante monoïque porte les deux types sur le même individu. Ces mots décrivent une organisation reproductive, pas une qualité commerciale. La présence de fleurs n’implique pas que toutes ont été fécondées ni qu’une graine soit déjà formée."],
    ["Décrire avant d’interpréter", "Pour identifier une partie de plante, commence par ce que tu observes : forme, position et relation avec les autres organes. Puis propose un terme et vérifie sa définition. Dire « je vois plusieurs folioles » est une observation plus précise que « cette plante a forcément tel effet ». Un dessin ou une photo ne remplace pas une analyse chimique.", "Dans le jeu, ouvre la fiche de L’Arbre Mère et retrouve la mention qui sépare le récit de la botanique. Tu peux ensuite essayer le premier mot croisé ou associer chaque organe à sa fonction. Les mots nouveaux deviennent plus faciles quand on les relie à une tâche concrète plutôt qu’à une liste à réciter."],
  ], "Sur une planche imaginaire figurent une feuille composée, une fleur et une racine. La feuille capte la lumière, la fleur intervient dans la reproduction et la racine relie la plante au sol. Ces fonctions peuvent être nommées sans connaître une variété commerciale.", "Prends trente secondes : explique à voix haute la différence entre une foliole et une fleur, puis entre pollinisation et fécondation. Vérifie tes mots dans la grille de la plante.", ["kew", "biology", "leaves", "plant-body", "buddy"], ["HH2026-001"], ["crossword-plant", "matching-plant"]),
  course("molecules", "Cannabinoïdes et terpènes", "Distinguer une molécule, un arôme et une mesure.", [
    ["Deux familles de mots", "Un cannabinoïde est une molécule : le cannabidiol, abrégé CBD, et le delta-9-tétrahydrocannabinol, abrégé THC, en sont deux exemples. Ces noms ne désignent pas une variété entière. Deux molécules présentes dans la même plante n’ont pas pour autant les mêmes propriétés. L’origine végétale ne suffit pas à conclure qu’une substance est sans risque.", "Les terpènes constituent une autre famille de molécules, dont plusieurs participent aux odeurs végétales. Limonène, pinène et myrcène sont des noms que l’on peut rencontrer dans une description. Un profil aromatique décrit une perception ou une composition ; il ne mesure pas à lui seul les cannabinoïdes et ne prédit pas un résultat médical."],
    ["À la surface de la plante", "Un trichome est une petite structure de surface, comparable à un poil au sens botanique. Certains trichomes sont glandulaires : ils produisent et accumulent des substances, notamment des cannabinoïdes et des terpènes. Tous les poils d’une plante ne jouent pas ce rôle. Il faut donc garder l’adjectif glandulaire quand c’est cette fonction qui nous intéresse.", "Un grain de pollen n’est pas un trichome : il intervient dans la reproduction. Une glande n’est pas non plus une graine. Ce vocabulaire permet de lire un schéma sans tout appeler résine. L’observation d’une surface peut décrire des structures ; elle ne donne pas une concentration fiable en CBD ou en THC."],
    ["Les mots des fiches", "La fiche d’un Buddy peut évoquer des fruits, du bois ou des épices. Ces mots sont des comparaisons sensorielles attribuées à cette fiche. Ils ne signifient pas que la plante contient le fruit nommé. Dans le Quartier, Harlequin porte les notes mangue et terre ; ACDC porte citron et diesel. Ce sont leurs profils de jeu, tirés des descriptions référencées.", "Une note citronnée ne démontre pas, à elle seule, qu’une molécule précise a été mesurée. Plusieurs composés et leurs proportions participent à une odeur. Pour parler de teneur en limonène, il faut une analyse appropriée, un échantillon identifié et une unité. On peut apprécier une description tout en gardant ce niveau d’exigence."],
    ["Du vocabulaire à la prudence", "CBD et THC sont différents, mais « différent du THC » ne veut pas dire « inactif ». Les autorités sanitaires rappellent que le CBD peut provoquer des effets indésirables et interagir avec des médicaments. Une fiche aromatique n’est ni une prescription ni un certificat de sécurité ; les situations personnelles relèvent d’un professionnel de santé.", "Pour réviser, sépare trois colonnes : structure de la plante, molécule, description sensorielle. Trichome va dans la première ; CBD dans la deuxième ; note mangue dans la troisième. Cette distinction est utile bien au-delà du chanvre : elle évite de transformer un mot de dégustation en conclusion chimique ou sanitaire."],
  ], "La fiche de Harlequin indique mangue et terre. On peut vérifier ces mots dans sa fiche, sans en déduire un taux de THC, un effet garanti ou la présence de mangue dans la plante.", "Classe mentalement pollen, trichome, CBD et citronné. Puis ouvre les fiches de Harlequin et d’ACDC et retrouve leurs deux notes, accessibles sans posséder les cartes.", ["biology", "profiles", "ameli", "buddy"], ["HH2026-004", "HH2026-005"], ["matching-molecules", "crossword-plant"]),
  course("profiles", "Variétés et profils", "Lire une fiche sans transformer un nom en garantie.", [
    ["Lire les rubriques séparément", "Une fiche peut réunir un nom, une histoire, des arômes et des résultats d’analyse. Ces rubriques n’apportent pas le même type d’information. Le nom sert à identifier une sélection ou une appellation commerciale ; une analyse décrit l’échantillon qui a été mesuré. Avant de comparer deux fiches, demande-toi si tu compares bien la même catégorie de données.", "Un chémotype classe des plantes selon leur composition chimique, par exemple selon les proportions relatives de certains cannabinoïdes. Il ne se confond ni avec un personnage du jeu, ni avec l’ensemble de son histoire génétique. Une composition est un caractère à documenter ; le nom seul ne permet pas d’en déduire les valeurs."],
    ["Des catégories imparfaites", "Dans le commerce, les mots indica et sativa peuvent servir d’étiquettes très générales. Une étude de 2021 a comparé des données génétiques, chimiques et ces étiquettes : elles ne résument pas correctement toute la variation entre les échantillons. Elles ne suffisent donc pas à annoncer un effet certain pour une personne.", "Une parenté documentée est plus précise qu’un simple nom ressemblant, mais elle ne garantit pas non plus une concentration identique dans chaque lot. Une fiche sérieuse indique à qui la description est attribuée et ce qui manque. Un point d’interrogation ou une origine non établie sont des informations utiles, pas des cases à remplir par une invention."],
    ["Le bon chiffre, avec son unité", "Un pourcentage est une proportion : 1 % en masse correspond à 1 gramme pour 100 grammes de l’échantillon considéré. Les milligrammes par gramme expriment aussi une proportion de masses : 1 % vaut 10 mg/g. Cette conversion ne dit rien de l’autorisation d’un produit et ne constitue pas un conseil de consommation.", "Le milligramme par millilitre rapporte au contraire une masse à un volume. On ne le compare pas directement à un pourcentage en masse sans connaître les informations nécessaires. Regarde aussi le numéro de lot, la date, la méthode et ce qui a réellement été analysé. Un résultat d’un autre lot ne décrit pas automatiquement le produit devant toi."],
    ["Lire deux Buddies", "Sour Space Candy est associée dans sa fiche aux notes pomme confite et cerise ; Hawaiian Haze aux notes ananas et floral. Ce sont des descriptions attribuées, utiles pour apprendre le vocabulaire. Leurs noms ne donnent pas une composition chiffrée et le mot Hawaiian n’est pas, à lui seul, une preuve du lieu de production d’un lot.", "Prends l’habitude de reformuler : « la fiche décrit… », « l’analyse de ce lot mesure… », « la source historique indique… ». Tu gardes ainsi une place à chaque information sans les mélanger. Lorsqu’aucune mesure n’est disponible, le résultat reste inconnu ; il ne devient pas zéro et ne doit pas être remplacé par une moyenne inventée."],
  ], "Deux emballages portent le même nom. L’un fournit une analyse datée du lot, l’autre seulement un adjectif. Le premier apporte une preuve sur les substances mesurées ; le second apporte une description. Aucun ne garantit un effet personnel.", "Sur les fiches de Sour Space Candy et Hawaiian Haze, retrouve les notes annoncées. Puis reformule une information avec « d’après la fiche » et une autre avec « pour cet échantillon analysé ».", ["profiles", "biology", "units", "analysis", "buddy"], ["HH2026-006", "HH2026-007"], ["matching-evidence"]),
  course("genetics", "Semences, génétique et sélection", "Séparer héritage génétique, caractères observés et qualité d’un lot.", [
    ["Information et observation", "Le génotype désigne une constitution génétique, ou les variantes présentes à des positions définies de l’ADN. Le phénotype désigne les caractères observables. La hauteur, une forme ou une composition mesurée relèvent du phénotype. Les gènes contribuent à ces caractères, mais leur expression dépend aussi du milieu et du développement.", "Imagine deux exemplaires d’un même livre lus sous des éclairages différents : le texte n’a pas nécessairement changé parce que tu le perçois autrement. Cette comparaison ne remplace pas la biologie ; elle aide seulement à retenir que différence observée et différence génétique ne sont pas synonymes. Pour attribuer un changement à une cause, une comparaison organisée est nécessaire."],
    ["Comparer pour sélectionner", "La sélection consiste à retenir des individus ou populations selon des caractères définis, puis à évaluer leur transmission. On peut viser différents objectifs : propriétés des fibres, caractéristiques des graines, adaptation ou régularité. Aucun caractère ne résume à lui seul la valeur d’une plante. Une préférence commerciale est encore autre chose qu’une preuve génétique.", "Pour interpréter un essai, il faut connaître les conditions et comparer des observations répétées. Si le milieu et les origines changent simultanément, il devient difficile de savoir ce qui explique le résultat. La diversité génétique représente des variantes au sein d’une population ; préserver cette diversité garde des possibilités d’adaptation et de recherche, sans promettre une réponse parfaite à chaque contrainte."],
    ["Que vérifie une semence ?", "La faculté germinative est un critère de qualité d’un lot de semences, évalué dans des conditions définies. Un résultat ne promet pas que toutes les graines donneront le même développement dans tous les milieux. L’identité variétale, la pureté et la qualité sanitaire sont d’autres questions : ce sont des critères distincts à examiner séparément.", "Le GEVES utilise notamment les études DHS : distinction, homogénéité et stabilité. Elles contribuent à décrire et reconnaître une variété. Homogénéité ne signifie pas que chaque plante sera identique dans toutes les situations ; stabilité concerne le maintien de caractères lors des cycles de multiplication prévus. Une inscription au catalogue ne doit pas être transformée en promesse thérapeutique."],
    ["Une histoire peut être corrigée", "La fiche de Cannatonic rapporte une parenté corrigée par son sélectionneur en 2015 : Reina Madre × NYCD. Pour notre question, il faut lire cette attribution précise. Une information commerciale, même publiée par le sélectionneur, ne devient pas une analyse indépendante de tous les produits vendus sous ce nom.", "Cet exemple montre l’intérêt de dater une information et de conserver sa provenance. Corriger un récit à partir d’une meilleure source est normal. Quand une généalogie n’est pas documentée, la bonne conclusion est qu’elle reste incertaine. Les fiches du Quartier distinguent justement histoire, origine et parenté pour permettre cette lecture attentive."],
  ], "Un lot peut avoir une bonne faculté germinative sans que l’on connaisse ses résultats dans tous les milieux. On a appris quelque chose sur un critère précis ; on n’a pas prouvé toutes les qualités possibles de la plante.", "Retrouve la parenté corrigée dans Cannatonic. Puis classe trois mentions : « forme observée », « variante d’ADN », « pourcentage de germination du lot ». Chacune répond à une question différente.", ["genotype", "phenotype", "geves", "catalogue", "germination", "buddy"], ["HH2026-003"], ["matching-evidence"]),
  course("history", "Histoire et traces", "Placer des repères et distinguer une trace de son interprétation.", [
    ["Des traces situées", "Une histoire solide commence par des objets, des textes et des analyses dont on connaît le contexte. À Jirzankal, dans les Pamirs, des résidus étudiés dans des braseros funéraires témoignent d’un usage du cannabis vers 500 avant notre ère. L’étude scientifique est parue en 2019 : la date de l’objet et celle de la publication sont différentes.", "Les auteurs interprètent ces traces dans le cadre de pratiques funéraires. Cela ne prouve ni que toutes les populations de l’époque avaient les mêmes pratiques, ni qu’il s’agit de la toute première utilisation humaine. Une découverte repousse ou précise ce qui est documenté ; elle n’efface pas l’incertitude sur ce qui n’a laissé aucune trace accessible."],
    ["Nommer puis comprendre", "En 1753, le nom Cannabis sativa L. est publié dans Species Plantarum de Linné, comme l’indique la base botanique de Kew. Cette date concerne une publication de nomenclature. Elle ne date pas l’apparition de la plante, sa première culture ou sa première rencontre avec les humains. Nommer scientifiquement et découvrir un usage sont des événements distincts.", "En 1964, Gaoni et Mechoulam publient un travail majeur sur l’isolement et la structure du THC. C’est un repère de chimie. Le mot découverte doit être précisé : isoler un composé, déterminer sa structure et comprendre son action correspondent à des questions différentes, souvent abordées par plusieurs équipes et à plusieurs dates."],
    ["Du composé au vivant", "En 1990, Matsuda et ses collègues publient le clonage et l’expression d’un récepteur cannabinoïde, aujourd’hui appelé CB1. En 1992, Devane et ses collègues identifient l’anandamide, une substance produite par l’organisme capable de se lier à ce type de récepteur. Ces travaux étudient le fonctionnement du vivant ; ils ne constituent pas un conseil d’utilisation d’un produit.", "Le préfixe endo signifie ici « à l’intérieur » : un endocannabinoïde est produit dans l’organisme, contrairement à un phytocannabinoïde issu d’une plante. L’histoire ne s’arrête donc pas à l’inventaire des molécules végétales. Une nouvelle méthode d’observation peut ouvrir un nouveau domaine de recherche, sans répondre immédiatement à toutes les questions de santé."],
    ["Dates de droit et dates de récit", "Le 29 décembre 2022, le Conseil d’État annule l’interdiction générale de vente des fleurs et feuilles de certaines variétés sans propriétés stupéfiantes. C’est un événement juridique français, à distinguer des découvertes scientifiques. Notre classement chronologique mélange volontairement les types de repères pour apprendre à les identifier ; les espaces entre cartes ne mesurent pas les durées.", "La fiche de Charlotte’s Web situe la sélection des frères Stanley au Colorado. Cette histoire attribuée à la fiche appartient à une trajectoire commerciale particulière. Elle ne raconte pas l’origine de toute l’espèce. Quand tu lis une histoire, garde ensemble quatre éléments : qui parle, de quoi, à quel endroit et à quelle époque."],
  ], "Un article publié en 2019 étudie un objet daté d’environ 500 avant notre ère. Dans le classement, la carte de l’usage ancien se place avant 1753, même si la publication scientifique est récente.", "Remets les six cartes de la frise dans l’ordre. Dis pour chacune s’il s’agit d’archéologie, de nomenclature, de chimie, de biologie ou de droit. Les boutons de déplacement permettent de jouer sans glisser-déposer.", ["archaeology", "kew", "thc1964", "receptor1990", "anandamide1992", "council2022", "buddy"], ["HH2026-002"], ["timeline-history"]),
  course("uses", "Les usages du chanvre", "Relier chaque matière à ses usages sans confondre graine et fleur.", [
    ["Une plante, plusieurs matières", "Une filière transforme différentes parties de la plante. Le chènevis est le nom donné à la graine de chanvre. La chènevotte correspond à la partie interne, ligneuse, de la tige. Les fibres se trouvent dans sa partie périphérique. Ces mots se ressemblent, mais ne désignent ni le même matériau, ni les mêmes transformations.", "Le défibrage sépare notamment les fibres et la chènevotte. Il ne fabrique pas une graine à partir d’une tige : il trie des constituants déjà différents. Cette distinction est le point de départ pour comprendre pourquoi une même récolte peut alimenter plusieurs débouchés. Un schéma « partie → matière → objet » est souvent plus utile qu’un catalogue de produits."],
    ["Des fibres aux objets", "Les fibres peuvent entrer dans des textiles, des papiers et des matériaux composites. Un composite associe des matériaux afin de combiner certaines propriétés ; une pièce contenant des fibres végétales n’est pas nécessairement composée uniquement de chanvre. Pour décrire l’objet correctement, on lit sa composition et l’usage auquel il est destiné.", "Pour le textile, la fibre doit passer par plusieurs transformations avant de devenir un fil puis un tissu. Le tissu est une structure de fils ; la plante entière n’est pas directement un vêtement. Dans l’atelier, relie la fibre au textile et distingue-la de la chènevotte destinée à d’autres usages. Les procédés industriels ne sont pas des recettes de fabrication de substances."],
    ["Le cœur de la tige et la graine", "La chènevotte est utilisée notamment pour des litières, du paillage et des produits de construction. Associée à un liant adapté, elle peut entrer dans un béton de chanvre. Ce nom désigne une famille de matériaux ; il ne signifie pas qu’elle remplace automatiquement une structure porteuse. Les performances et conditions d’emploi doivent être documentées pour chaque produit.", "Les graines et leurs dérivés peuvent avoir des usages alimentaires sous les conditions applicables. Une huile de graines de chanvre est différente d’une huile enrichie en CBD : même contenant ou même couleur ne signifie pas même composition. Le mot huile décrit une forme, pas toute la liste des ingrédients. Cette lecture sera reprise dans le cours sur le droit."],
    ["Évaluer un usage avec précision", "Un matériau d’origine végétale n’a pas automatiquement le meilleur bilan dans tous les contextes. Sa fabrication, son transport, sa durée de vie et sa fin de vie comptent aussi. Pour comparer deux objets, précise d’abord le service rendu : une feuille de papier et une paroi isolante ne se mesurent pas avec le même indicateur.", "La diversité des débouchés explique l’intérêt industriel du chanvre, mais elle ne dispense pas de normes de qualité ou de sécurité. Demande quelle partie est utilisée, comment le produit est défini et quelle preuve soutient la propriété annoncée. C’est la même habitude que pour les fiches : nommer l’information et rester dans les limites de ce qui est réellement documenté."],
  ], "Sur une table, un sachet de graines, une poignée de fibres et des petits fragments de chènevotte portent tous le mot chanvre. Ce mot commun ne les rend pas interchangeables : chacun a des fonctions et des règles d’usage propres.", "Fais le trajet « tige → fibres → fil → tissu », puis « tige → chènevotte → matériau de construction ». Retrouve chènevis et chènevotte dans la seconde grille ; le corrigé conserve leurs accents.", ["uses", "eu-hemp", "food2026", "lifecycle"], [], ["crossword-uses", "matching-plant"]),
  course("evidence", "Enquête et esprit critique", "Choisir la preuve qui répond à la question posée.", [
    ["Toutes les sources ne disent pas la même chose", "Un témoignage raconte une expérience ; une fiche commerciale décrit un produit ; une étude rapporte une méthode et des résultats. Ces documents peuvent tous apporter une information, mais pas la même. Avant de demander si une source est bonne, précise la question : cherche-t-on un arôme annoncé, une composition mesurée ou un effet établi ?", "Une source primaire est proche du travail original : article présentant une expérience, texte réglementaire ou décision de justice. Un résumé peut faciliter la lecture, mais il faut pouvoir remonter au document qui soutient l’affirmation. Une référence prestigieuse, si elle ne traite pas du point discuté, ne constitue pas une preuve pertinente."],
    ["Un résultat a un périmètre", "Une analyse concerne un échantillon et les paramètres réellement recherchés. Elle comporte un numéro de lot, une date, une méthode et des limites. Un résultat non détecté signifie que la méthode n’a pas détecté la substance dans ses conditions ; cela n’établit pas une absence absolue. Un document incomplet mérite une demande d’information, pas une valeur inventée.", "Les enquêtes françaises sur des produits présentés comme du CBD montrent l’intérêt de comparer étiquetage et mesure. Le résultat d’une enquête porte sur les produits étudiés : on ne transforme pas automatiquement leur proportion en celle de tout le marché. La manière de choisir les échantillons est aussi importante que leur nombre pour comprendre ce qui peut être généralisé."],
    ["Comparer des nombres comparables", "Deux chiffres ne se comparent qu’avec leurs unités et leur définition. Dans un exemple purement scolaire, 2 % en masse correspond à 20 mg/g. Cela ne signifie pas 2 mg/g. Une concentration rapporte une quantité à une autre ; une masse totale et une concentration ne décrivent donc pas la même chose.", "Corrélation signifie que deux observations varient ensemble ; elle ne démontre pas, seule, que l’une cause l’autre. Pour une affirmation d’effet, on recherche un protocole permettant des comparaisons pertinentes et on examine les autres explications possibles. Un récit avant/après sans comparaison peut être intéressant, mais il ne permet pas d’écarter toutes les causes concurrentes."],
    ["Enquêter dans le Quartier", "La fiche d’Elektra affiche les notes orange et chocolat. Elle permet de répondre à « quelles notes la fiche décrit-elle ? ». Elle ne permet pas de conclure « ce Buddy garantit tel effet ». Le statut de l’information reste une description attribuée. Le jeu peut ainsi servir d’exercice de lecture sans transformer ses profils en vérités universelles.", "Avant de partager une affirmation, prépare une phrase complète : « Selon telle source, dans telles conditions, on observe ceci ; cela ne renseigne pas encore sur cela. » Vérifie aussi la date quand les règles ou connaissances évoluent. Dire ce que l’on ignore est une compétence d’enquête : cela laisse la place à une meilleure mesure ou à une source plus pertinente."],
  ], "Une photo d’étiquette indique une teneur ; une analyse datée du lot fournit une mesure. Si les valeurs diffèrent, il faut vérifier l’identité de l’échantillon et le document. On ne choisit pas simplement le chiffre qui confirme son idée.", "Dans les associations, relie chaque document à ce qu’il peut établir. Puis retrouve les notes d’Elektra et formule une réponse qui attribue clairement cette information à sa fiche.", ["analysis", "units", "profiles", "buddy"], ["HH2026-009"], ["matching-evidence", "crossword-uses"]),
  course("biodiversity", "Biodiversité et agriculture", "Expliquer un intérêt écologique sans en faire une règle universelle.", [
    ["Une parcelle dans un paysage", "La biodiversité comprend une diversité de gènes, d’espèces et d’écosystèmes. Une parcelle agricole fait partie d’un paysage : haies, bandes enherbées et cultures voisines influencent les organismes que l’on y rencontre. Observer une espèce dans un champ est un point de départ ; comprendre son rôle demande de regarder aussi les relations et les conditions autour d’elle.", "Un auxiliaire est un organisme qui contribue à un service utile dans le système considéré, par exemple un prédateur de certains ravageurs. Tous les insectes ne sont donc pas des ennemis de la plante. Inversement, constater un auxiliaire ne prouve pas que tout problème est réglé. La diversité des fonctions compte autant que la présence d’un nom sur une liste."],
    ["Pollen et abeilles", "Le chanvre est surtout pollinisé par le vent. Cela n’empêche pas des abeilles de visiter ses fleurs mâles pour collecter du pollen, comme l’ont observé les chercheurs de Cornell. Pollen et nectar sont deux ressources différentes : dans ces observations, le chanvre fournit du pollen, pas de nectar. Une visite d’abeille ne suffit donc pas à faire du chanvre une plante nectarifère.", "La valeur de cette ressource dépend du moment, de la présence de fleurs et des ressources voisines. Une étude menée dans l’État de New York décrit ce contexte ; elle n’établit pas le même résultat dans chaque région. Pour comparer deux paysages, il faudrait des observations adaptées, plutôt que reproduire un chiffre sans vérifier les conditions."],
    ["Rotations et besoins", "Une rotation est une succession de cultures sur une même parcelle au fil des saisons ou années. Diversifier cette succession peut aider à répartir des contraintes et à organiser un système agricole. Terres Inovia décrit le chanvre comme un précédent intéressant dans certaines rotations. Ce repère agronomique n’est pas une garantie de rendement ou de qualité pour chaque terrain.", "Comme les autres plantes, le chanvre a besoin d’eau, de lumière et d’éléments minéraux. Une adaptation à certains épisodes secs ne signifie pas absence de besoin en eau. La profondeur du sol, le climat et le stade de développement peuvent modifier la réponse observée. Notre cours explique ces relations générales ; il ne donne pas d’itinéraire de production."],
    ["Des mots précis pour l’environnement", "« Naturel », « rustique » ou « écologique » sont des mots trop larges si l’on ne précise pas le critère. Parle-t-on d’eau, d’habitat pour des organismes ou d’émissions sur un cycle de vie ? Les unités, le lieu et la période changent l’interprétation. Une comparaison équitable demande de rendre les services comparés et les limites de l’étude explicites.", "Tu peux appliquer cette vigilance aux descriptions du jeu. Les notes pomme verte et poivre de Suver Haze sont un profil de fiche ; elles ne prouvent ni un avantage écologique ni une exigence de la plante. Savoir passer d’un registre à l’autre, sans tout mélanger, aide à lire aussi bien un paysage qu’une fiche de Buddy."],
  ], "Une abeille récolte du pollen sur une fleur mâle. L’observation est compatible avec une pollinisation principalement par le vent et ne prouve pas la présence de nectar. Deux phénomènes peuvent coexister sans avoir la même fonction.", "Explique pourquoi « résistant à la sécheresse » ne signifie pas « sans eau ». Puis compare les mots de la fiche Suver Haze à ceux d’une observation écologique : quelles informations décrivent réellement un environnement ?", ["bees", "biology", "agriculture", "plant-body", "buddy"], ["HH2026-010"], ["matching-plant"]),
  course("law", "France et Union européenne", "Repérer la règle applicable à une plante, à un produit et à un usage.", [
    ["Un repère daté", "Ce cours a été vérifié le 11 novembre 2026. Les règles peuvent évoluer : pour une situation réelle, il faut consulter les textes en vigueur et les autorités compétentes. Le mot chanvre ne constitue pas à lui seul une autorisation. On distingue la variété végétale, la composition du produit, son mode de commercialisation et l’usage envisagé.", "L’arrêté français du 30 décembre 2021 prévoit notamment des variétés de Cannabis sativa L. inscrites aux catalogues concernés avec une teneur en delta-9-THC ne dépassant pas 0,30 %. Ce cadre comporte d’autres conditions. Le nombre isolé ne permet pas de conclure qu’une plante, une denrée ou tout usage est licite."],
    ["Lire les décisions avec les textes", "Le 29 décembre 2022, le Conseil d’État a annulé l’interdiction générale et absolue de commercialiser les fleurs et feuilles des variétés concernées. Une lecture du texte initial qui conserve cette interdiction comme si elle était toujours applicable est donc incomplète. Il faut lire le texte avec les décisions qui en modifient la portée.", "Dans l’Union européenne, les conditions agricoles de la PAC font notamment référence à des variétés répondant au critère de THC et à des semences certifiées inscrites au catalogue commun. Il s’agit de conditions pour ce cadre agricole. Une règle d’éligibilité à une aide n’est pas une autorisation générale de tous les produits vendus aux consommateurs."],
    ["Une denrée a ses propres règles", "Le ministère de l’Agriculture a rappelé le 20 mai 2026 que les denrées contenant du CBD ajouté parmi leurs ingrédients ne disposent pas de l’autorisation requise au titre des nouveaux aliments. La présence d’un produit dans un commerce ne prouve pas sa conformité. Un taux de THC faible ne remplace pas cette autorisation.", "Les graines de chanvre et leurs dérivés, comme l’huile de graines, relèvent d’une situation distincte, avec leurs propres conditions, dont les teneurs maximales applicables en THC et l’absence d’enrichissement en cannabinoïdes. On ne peut pas remplacer « huile de graines » par « huile de CBD » dans un raisonnement : les mots décrivent des produits différents."],
    ["Produit vendu et usage autorisé", "La Cour de cassation a rappelé le 21 juin 2023 que la vente licite d’un produit contenant du THC n’écarte pas l’infraction de conduite après usage de stupéfiants constaté. Une étiquette CBD ne garantit donc pas un résultat négatif au dépistage. Ce repère de droit ne propose ni délai de sécurité ni méthode pour contourner un contrôle.", "Pour examiner une affirmation réglementaire, relève le territoire, la date, le texte, le produit et l’usage. Si un de ces éléments manque, reste prudent dans la conclusion. Le cours fournit des repères de lecture ; pour trancher une situation concrète, une vérification actuelle et adaptée reste nécessaire. Les sources officielles sont disponibles avec chaque question concernée."],
  ], "Un flacon d’huile de graines et un aliment enrichi en CBD peuvent tous deux porter une feuille de chanvre. Leur présentation graphique ne les place pas sous un régime identique ; les ingrédients et la catégorie du produit comptent.", "Sur une affirmation « autorisé sous 0,3 % », retrouve les informations manquantes : dans quel pays, à quelle date, pour quel produit et pour quel usage ? Réécris-la en conservant seulement ce que la source établit.", ["decree", "council2022", "eu-hemp", "food2026", "driving"], [], ["matching-evidence", "timeline-history"]),
  course("prevention", "Prévention et limites des promesses", "Reconnaître les situations où une étiquette ne suffit pas.", [
    ["Naturel ne veut pas dire sans risque", "Une substance végétale peut agir sur l’organisme et provoquer des effets indésirables. Le CBD et le THC sont différents ; cette différence ne rend pas tout produit présenté comme CBD inoffensif. Les risques dépendent notamment de la composition réelle, de la personne et des associations avec d’autres substances. Un nom de variété ou une note aromatique ne permet pas de les déduire.", "Les autorités sanitaires signalent notamment une possible somnolence, des troubles digestifs ou d’autres manifestations après prise de CBD. Ce cours ne pose aucun diagnostic. Une information générale sert à reconnaître un problème et à chercher une aide adaptée ; elle ne remplace pas l’examen d’une situation personnelle ni la surveillance d’un traitement."],
    ["Les interactions comptent", "Une interaction survient lorsqu’une substance modifie les effets d’une autre. L’ANSM avertit que le CBD peut modifier l’efficacité de certains médicaments ou accentuer leurs effets indésirables. Le fait qu’un médicament soit disponible sans ordonnance ne supprime pas cette question. Le médecin ou le pharmacien doit connaître les produits utilisés pour pouvoir conseiller correctement.", "Si une personne suit un traitement et envisage un produit au CBD, elle en parle à un professionnel de santé. Elle ne modifie pas seule son traitement pour faire de la place à un produit. L’école ne fournit ni dosage ni combinaison : son objectif est d’aider à identifier l’information manquante et le bon interlocuteur."],
    ["L’étiquette n’est pas toute la composition", "L’ANSM et l’ANSES ont alerté en juin 2025 sur des intoxications liées à des produits présentés comme du CBD et contenant d’autres substances, parfois non annoncées. Un emballage familier, un goût sucré ou une vente sur internet ne constitue pas une garantie de composition. Les produits doivent être tenus hors de portée des enfants.", "En cas d’effet indésirable, il faut arrêter le produit en cause et demander un avis médical ou au centre antipoison. En cas de malaise grave, de difficulté à respirer ou de perte de connaissance, appeler les secours au 15 ou au 112. Conserver l’emballage et les informations sur le produit peut aider les professionnels à comprendre l’exposition."],
    ["Reconnaître une promesse excessive", "Un témoignage favorable ne démontre pas une efficacité médicale. Un produit de bien-être et un médicament autorisé, prescrit et suivi ne sont pas interchangeables. De même, une ancienne utilisation ne suffit pas à prouver une sécurité actuelle. Il faut connaître le produit exact, la question étudiée et les limites des données pour évaluer une affirmation.", "Dans le Quartier, Lifter est décrit par les notes myrtille et fromage. Ces mots restent un profil de fiche, sans promesse de soin. Le meilleur réflexe est de pouvoir dire ce que l’information permet de savoir et ce qu’elle ne permet pas de conclure. Finir le quiz signifie maîtriser ces repères, pas recevoir une autorisation de consommer."],
  ], "Une personne trouve un produit « naturel » et prend déjà un médicament. Le mot naturel ne répond pas à la question des interactions : l’information utile doit être discutée avec son médecin ou son pharmacien.", "Relève une promesse comme « aucun risque » ou « effet garanti ». Cherche ce qui manquerait pour la soutenir. Termine en retrouvant les notes de Lifter et en expliquant pourquoi elles ne constituent pas une preuve médicale.", ["ameli", "interactions", "alert2025", "poison", "emergency", "buddy"], ["HH2026-008"], ["matching-evidence"]),
];
export function getKqSchoolCourse(id: string): KqSchoolCourse | undefined { return KQ_SCHOOL_COURSES.find(item => item.id === id); }

type QuestionRow = readonly [prompt: string, options: readonly [string, string, string, string], section: number, sourceIds: readonly string[], buddyCodes?: readonly string[], difficulty?: "easy" | "medium"];
function moduleContent(id: string, rows: readonly QuestionRow[]): KqSchoolModule {
  const lesson = getKqSchoolCourse(id)!;
  return { id, title: lesson.title, version: KQ_SCHOOL_CONTENT_VERSION, questions: rows.map(([prompt, labels, section, sourceIds, buddyCodes, difficulty], index) => {
    const options = labels.map((text, optionIndex) => ({ id: String.fromCharCode(97 + optionIndex), text }));
    // Presentation order is independent of stable option identities and of the answer key.
    const order = [[2, 0, 3, 1], [1, 3, 0, 2], [3, 2, 1, 0]][index % 3];
    return { id: `${id}-q${String(index + 1).padStart(2, "0")}`, prompt, options: order.map(i => options[i]), difficulty: difficulty ?? "easy", lessonId: id, sectionId: `${id}-${section}`, sources: sources(...sourceIds), ...(buddyCodes ? { buddyCodes } : {}) };
  }) };
}

